      entry,
    ]),
  );
  const evidence = Object.entries(categorySources).map(([category, fileName]) =>
    gateEvidence(
      workspace,
      category,
      'qualification-proof',
      path.join(ROOT, 'framework', 'agent-work', 'evidence', 'kfd-7', fileName),
      `kfd-7-${category}`,
