  evidence.push(
    gateEvidence(
      workspace,
      'independent-review',
      'independent-review',
      actionContractPath,
      'kfd-7-independent-review',
    ),
  );
  evidence.push(
    gateEvidence(
      workspace,
      'kfd-7-negative',
      'negative-fixture',
      path.join(
        ROOT,
        'framework',
        'agent-work',
        'evidence',
        'kfd-7',
        'negative-invalid-transition.json',
      ),
      'kfd-7-negative',
    ),
  );
  const profile = {
    ...baseProfile,
    evidenceObligations: Object.keys(categorySources).map((category) => ({
      category,
      status: 'passed',
      artifactRefs: [category],
      residualRisk:
        previousObligations.get(category)?.residualRisk ||
        'Evidence is bounded to the Kungfu Product Profile.',
    })),
    activation: {
      decision: 'activate',
      evidenceCut: `git:implementation@${sourceSha}+buildchain-product-gate@runtime`,
      independentReview: actionContract.activation.independentReview,
      productWitnesses: actionContract.activation.productWitnesses,
      residualRisk: actionContract.activation.residualRisk,
    },
    domainProfile: {
      id: actionContract.profile.id,
      version: actionContract.profile.version,
      product: actionContract.profile.product,
      implementation: `git+https://github.com/kungfu-systems/kungfu.git@${sourceSha}#framework/core/src/python/kungfu/agent/work_profile.py`,
      qualificationStatus: 'qualified',
    },
    nonClaims: [
      'This Product Profile does not define universal KFD-7 lifecycle vocabulary.',
      'The Buildchain gate does not replace independent product activation or release qualification.',
    ],
  };
  const records = [
    {
      role: 'domain-profile',
      ...writeGateJson(
        workspace,
        gateRelativePath('kfd-7', 'domain-profile.json'),
        profile,
      ),
    },
  ];
  return productGateEnvelope({
    standard: 'kfd-7',
    standardRevision: standards.standards['kfd-7'].revision,
    sourceSha,
    checkedAt,
    records,
    evidence,
    nonClaims: [
      'KFD-7 qualification is bounded to the Kungfu Product Profile and exact source cut.',
      'A passed Buildchain gate does not certify other Domain Profiles.',
    ],
  });
}

async function buildProductGates({ write, sourceSha, checkedAt }) {
  const workspace = write
    ? ROOT
    : fs.mkdtempSync(path.join(os.tmpdir(), 'kungfu-kfd-product-gates-'));
  try {
    const standards = requireAsset(
      '@kungfu-tech/kfd',
      'standards.json',
      __filename,
    ).parsed;
    const inputs = [
      kfd4GateInput({ workspace, sourceSha, checkedAt, standards }),
      kfd5GateInput({ workspace, sourceSha, checkedAt, standards }),
      kfd7GateInput({ workspace, sourceSha, checkedAt, standards }),
    ];
    const gates = [];
    for (const input of inputs) {
      const gate = await runtime.productGates.evaluateKfdProductGate({
        cwd: workspace,
        input,
        expectedSourceSha: sourceSha,
        checkedAt,
      });
      const validation = runtime.productGates.validateKfdProductGateResult(
        gate,
        {
          expectedSourceSha: sourceSha,
          checkedAt,
        },
      );
      if (!validation.valid) {
        throw new Error(
          `${input.standard} product-gate result is invalid: ${JSON.stringify(validation.issues)}`,
        );
      }
      if (gate.status !== 'passed') {
        throw new Error(
          `${input.standard} product gate must pass for the checked-in exact-source evidence cut: ${JSON.stringify(gate.issues)}`,
        );
      }
      gates.push(gate);
      if (write) {
        writeJson(
          path.join(KFD_PRODUCT_GATE_RUNTIME_DIR, input.standard, 'input.json'),
          input,
        );
        writeJson(
          path.join(KFD_PRODUCT_GATE_RUNTIME_DIR, input.standard, 'gate.json'),
          gate,
        );
      }
    }
    const matrix = readJson(KFD_SUPPORT_MATRIX_PATH);
    const projection = runtime.productGates.createKfdSupportProjection({
      matrix,
      matrixRoot: `sha256:${sha256File(KFD_SUPPORT_MATRIX_PATH)}`,
      gateResults: gates,
      expectedSourceSha: sourceSha,
      checkedAt,
    });
    const projectionValidation =
      runtime.productGates.validateKfdSupportProjection(projection, {
        expectedSourceSha: sourceSha,
        checkedAt,
      });
    if (!projectionValidation.valid) {
      throw new Error(
        `KFD support projection is invalid: ${JSON.stringify(projectionValidation.issues)}`,
      );
    }
    if (write) writeJson(KFD_SUPPORT_PROJECTION_PATH, projection);
    return {
      sourceSha,
      checkedAt,
      inputs,
      gates,
      projection,
    };
  } finally {
    if (!write) fs.rmSync(workspace, { recursive: true, force: true });
  }
}

function buildSummary({
  registry,
  upstreamAggregate,
  kfd1Witness,
  kfd1Gate,
  kfd1VerifyResult,
  kfd2Summary,
  productGates,
  prebuildWitness,
  strictAudit,
}) {
  return {
    schemaVersion: 1,
    contract: 'kungfu-buildchain-kfd-evidence-summary',
    product: registry.product,
    buildchain: {
      minimumVersion: '3.0.0',
      releasePassportInputs: {
        kfd1WitnessJsons: [rel(KFD1_WITNESS_PATH)],
        kfd1ReleaseGate: rel(KFD1_RELEASE_GATE_PATH),
        kfd2ClaimJsons: (kfd2Summary.buildchainProjection?.claims || []).map(
          (claim) =>
            claim.path
              ? rel(claim.path)
              : `${rel(KFD2_OUTPUT_DIR)}/claims/${claim.id}.json`,
        ),
        kfd3PrebuildWitnessJsons: [rel(KFD3_PREBUILD_WITNESS_PATH)],
        kfd3ArtifactVerifyCommand: ARTIFACT_VERIFY_COMMAND,
        kfdSupportMatrixJson: rel(KFD_SUPPORT_MATRIX_PATH),
        kfdProductGateJsons: KFD_PRODUCT_GATE_PATHS.map(rel),
      },
    },
    kfd1: {
      witness: rel(KFD1_WITNESS_PATH),
      packagedWitness: rel(SDK_KFD1_WITNESS_PATH),
      releaseGate: rel(KFD1_RELEASE_GATE_PATH),
      packagedReleaseGate: rel(SDK_KFD1_RELEASE_GATE_PATH),
      verifyResult: rel(KFD1_VERIFY_RESULT_PATH),
      packagedVerifyResult: rel(SDK_KFD1_VERIFY_RESULT_PATH),
      id: kfd1Witness.id,
      standard: kfd1Witness.standard,
      status: kfd1Gate.status,
      verifyOk: kfd1VerifyResult.ok,
      releaseGateSha256: `sha256:${sha256RenderedJson(kfd1Gate)}`,
      surfaces: Array.isArray(kfd1Witness.surfaces)
        ? kfd1Witness.surfaces.length
        : 0,
    },
    kfd2: {
      outputDir: rel(KFD2_OUTPUT_DIR),
      packagedOutputDir: rel(SDK_KFD2_OUTPUT_DIR),
      releaseClaims: `${rel(KFD2_OUTPUT_DIR)}/release-claims.json`,
      packagedReleaseClaims: `${rel(SDK_KFD2_OUTPUT_DIR)}/release-claims.json`,
      claimCount: kfd2Summary.buildchainProjection?.claimCount || 0,
      releaseClaimsSha256: `sha256:${kfd2Summary.releaseClaims?.sha256 || ''}`,
    },
    kfd3: {
      registry: KFD3_DEFAULT_REGISTRY_PATH,
      registryMode: strictAudit.mode,
      strictRegistryAudit: {
        ok: strictAudit.ok,
        issueCount: strictAudit.summary.issueCount,
        sourceOfTruth: strictAudit.sourceOfTruth,
      },
      upstreamAggregate: 'developer/sdk/kfd/upstream-aggregate.json',
      upstreamCount: upstreamAggregate.summary.upstreamCount,
      prebuildWitness: rel(KFD3_PREBUILD_WITNESS_PATH),
      artifactWitness: rel(KFD3_ARTIFACT_WITNESS_PATH),
      query: rel(KFD3_QUERY_PATH),
      surfaceCount: registry.surfaces.length,
      collaborationInterfaceDigest:
        prebuildWitness.collaborationInterfaceDigest,
    },
    productGates: {
      sourceSha: productGates.sourceSha,
      projection: rel(KFD_SUPPORT_PROJECTION_PATH),
      projectionRoot: productGates.projection.projectionRoot,
      status: productGates.projection.status,
      gates: productGates.gates.map((gate) => ({
        standard: gate.standard,
        status: gate.status,
        gateRoot: gate.gateRoot,
        issueCount: gate.issues.length,
        qualifying: gate.qualifying,
        selfCertified: gate.selfCertified,
      })),
    },
  };
}

async function runArtifactWitness(options) {
  const upstreamAggregate = buildUpstreamKfdAggregate();
  const registry = buildKfd3Registry(upstreamAggregate);
  assertCurrent(KFD3_REGISTRY_PATH, registry, 'Buildchain KFD-3 registry');
  assertStrictBuildchainAudit(buildStrictBuildchainAudit(registry));
  const witness = buildKfd3ArtifactWitness(registry, { runVerify: true });
  if (options.json) process.stdout.write(renderJson(witness));
  else
    process.stdout.write(
      `[kfd] artifact witness ${witness.id} surfaces=${witness.exposedSurfaces.length}\n`,
    );
}

async function runCheckOrWrite(options) {
  const upstreamAggregate = buildUpstreamKfdAggregate();
  const registry = buildKfd3Registry(upstreamAggregate);
  const kfd1Witness = buildKfd1Witness();
  const kfd1Gate = buildKfd1ReleaseGate(kfd1Witness);
  const kfd1VerifyResult = buildKfd1VerifyResult(kfd1Gate);
  if (!kfd1VerifyResult.ok) {
    throw new Error(
      `KFD-1 release gate verification failed:\n${kfd1VerifyResult.issues
        .map((issue) => `- ${issue.code || 'kfd-1'}: ${issue.message || issue}`)
        .join('\n')}`,
    );
  }
  const kfd2Summary = options.write
    ? writeKfd2PackagedOutputs(KFD2_OUTPUT_DIR)
    : assertCurrentKfd2Output(KFD2_OUTPUT_DIR, 'Buildchain KFD-2 output');
  if (options.write) {
    writeIfChanged(KFD3_REGISTRY_PATH, registry);
    writeIfChanged(SDK_KFD3_CANONICAL_REGISTRY_PATH, registry);
    writeIfChanged(SDK_KFD_UPSTREAM_AGGREGATE_PATH, upstreamAggregate);
    writeJson(SDK_KFD1_WITNESS_PATH, kfd1Witness);
    writeJson(SDK_KFD1_RELEASE_GATE_PATH, kfd1Gate);
    writeJson(SDK_KFD1_VERIFY_RESULT_PATH, kfd1VerifyResult);
    writeKfd2PackagedOutputs(SDK_KFD2_OUTPUT_DIR);
  } else {
    assertCurrent(KFD3_REGISTRY_PATH, registry, 'Buildchain KFD-3 registry');
    assertCurrent(
      SDK_KFD3_CANONICAL_REGISTRY_PATH,
      registry,
      'SDK packaged canonical KFD-3 registry',
    );
    assertCurrent(
      SDK_KFD_UPSTREAM_AGGREGATE_PATH,
      upstreamAggregate,
      'SDK packaged upstream KFD aggregate',
    );
    assertCurrent(KFD1_WITNESS_PATH, kfd1Witness, 'Buildchain KFD-1 witness');
    assertCurrent(
      KFD1_RELEASE_GATE_PATH,
      kfd1Gate,
      'Buildchain KFD-1 release gate',
    );
    assertCurrent(
      KFD1_VERIFY_RESULT_PATH,
      kfd1VerifyResult,
      'Buildchain KFD-1 verify result',
    );
    assertCurrent(
      SDK_KFD1_WITNESS_PATH,
      kfd1Witness,
      'SDK packaged KFD-1 witness',
    );
    assertCurrent(
      SDK_KFD1_RELEASE_GATE_PATH,
      kfd1Gate,
      'SDK packaged KFD-1 release gate',
    );
    assertCurrent(
      SDK_KFD1_VERIFY_RESULT_PATH,
      kfd1VerifyResult,
      'SDK packaged KFD-1 verify result',
    );
    assertCurrentKfd2Output(SDK_KFD2_OUTPUT_DIR, 'SDK packaged KFD-2 output');
  }
  const strictAudit = buildStrictBuildchainAudit(registry);
  assertStrictBuildchainAudit(strictAudit);
  const sourceSha = resolveKfdEvidenceSourceSha({ write: options.write });
  const checkedAt = resolveKfdProductGateCheckedAt({
    write: options.write,
    now: () => new Date().toISOString(),
    retainedGateResults: KFD_PRODUCT_GATE_PATHS.map(readOptionalJson),
    sourceSha,
    commitTimestamp: (commit) =>
      gitValue(['show', '-s', '--format=%cI', commit]),
  });
  const prebuildWitness = buildKfd3PrebuildWitness(registry, sourceSha);
  const artifactWitness = buildKfd3ArtifactWitness(registry, {
    runVerify: true,
  });
  const query = await buildQuery(registry);
  const productGates = await buildProductGates({
    write: options.write,
    sourceSha,
    checkedAt,
  });
  const summary = buildSummary({
    registry,
    upstreamAggregate,
    kfd1Witness,
    kfd1Gate,
    kfd1VerifyResult,
    kfd2Summary,
    productGates,
    prebuildWitness,
    strictAudit,
  });

  if (options.write) {
    writeJson(KFD1_WITNESS_PATH, kfd1Witness);
    writeJson(KFD1_RELEASE_GATE_PATH, kfd1Gate);
    writeJson(KFD1_VERIFY_RESULT_PATH, kfd1VerifyResult);
    writeJson(KFD3_PREBUILD_WITNESS_PATH, prebuildWitness);
    writeJson(KFD3_ARTIFACT_WITNESS_PATH, artifactWitness);
    writeJson(KFD3_QUERY_PATH, query);
    writeJson(SUMMARY_PATH, summary);
  } else {
    assertCurrent(
      KFD3_PREBUILD_WITNESS_PATH,
      prebuildWitness,
      'Buildchain KFD-3 prebuild witness',
    );
    assertCurrent(
      KFD3_ARTIFACT_WITNESS_PATH,
      artifactWitness,
      'Buildchain KFD-3 artifact witness',
    );
    assertCurrent(KFD3_QUERY_PATH, query, 'Buildchain KFD-3 capability query');
    for (let index = 0; index < productGates.gates.length; index += 1) {
      assertCurrentIfPresent(
        KFD_PRODUCT_GATE_INPUT_PATHS[index],
        productGates.inputs[index],
        `${KFD_PRODUCT_GATE_STANDARDS[index]} product-gate input`,
      );
      assertCurrentIfPresent(
        KFD_PRODUCT_GATE_PATHS[index],
        productGates.gates[index],
        `${KFD_PRODUCT_GATE_STANDARDS[index]} product gate`,
      );
    }
    assertCurrentIfPresent(
      KFD_SUPPORT_PROJECTION_PATH,
      productGates.projection,
      'Buildchain KFD support projection',
    );
    assertCurrentIfPresent(
      SUMMARY_PATH,
      summary,
      'Buildchain KFD evidence summary',
    );
  }

  const output = {
    ok: true,
    mode: options.write ? 'write' : 'check',
    registry: {
      path: KFD3_DEFAULT_REGISTRY_PATH,
      packagedPath: 'developer/sdk/kfd/kfd-3-surfaces.json',
      mode: strictAudit.mode,
      sourceOfTruth: strictAudit.sourceOfTruth,
      surfaceCount: registry.surfaces.length,
      sha256: options.write
        ? sha256File(KFD3_REGISTRY_PATH)
        : sha256Text(renderJson(registry)),
      strictAudit,
    },
    summary,
  };
  if (options.json) process.stdout.write(renderJson(output));
  else
    process.stdout.write(
      `[kfd] ok: KFD-1 witness, ${summary.kfd2.claimCount} KFD-2 claim(s), ${summary.kfd3.surfaceCount} KFD-3 surface(s)\n`,
    );
}
async function runQuery(options) {
  const upstreamAggregate = buildUpstreamKfdAggregate();
  const registry = buildKfd3Registry(upstreamAggregate);
  const query = await buildQuery(registry);
  if (options.json) process.stdout.write(renderJson(query));
  else
    process.stdout.write(
      `[kfd] query: ${query.product} capabilities=${query.capabilities?.length || 0}\n`,
    );
}

try {
  const options = parseArgs(process.argv.slice(2));
  runtime = await loadBuildchainKfdRuntime();
  if (!runtime && options.check)
    process.stdout.write(renderJson(checkColdBuildchainKfd(ROOT)));
  else if (!runtime)
    throw new Error(
      'Buildchain KFD runtime is required for write, query, and artifact-witness modes',
    );
  else if (options.artifactWitness) await runArtifactWitness(options);
  else if (options.query) await runQuery(options);
  else await runCheckOrWrite(options);
} catch (error) {
  console.error(
    `[kfd] ${error instanceof Error ? error.message : String(error)}`,
  );
  process.exit(1);
}

#!/usr/bin/env node
// SPDX-License-Identifier: Apache-2.0
// @ts-check

import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import {
  ReadonlyGithubSlugger,
  parseReadonlyMarkdown,
} from './docs-markdown-readonly.mjs';
import { validateDocumentMetadata } from './document-metadata-contract.mjs';
import { validateVocabularyContract } from './vocabulary-contract.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MODULES = process.env.KUNGFU_DOCS_MODULES;
const requireFrom = createRequire(
  MODULES
    ? path.join(path.resolve(MODULES), '..', 'package.json')
    : import.meta.url,
);
let GithubSlugger = ReadonlyGithubSlugger;
let MarkdownIt = null;
try {
  GithubSlugger = (
    await import(pathToFileURL(requireFrom.resolve('github-slugger')).href)
  ).default;
  MarkdownIt = (
    await import(pathToFileURL(requireFrom.resolve('markdown-it')).href)
  ).default;
} catch (error) {
  if (
    /** @type {NodeJS.ErrnoException} */ (error).code !== 'MODULE_NOT_FOUND' &&
    /** @type {NodeJS.ErrnoException} */ (error).code !== 'ERR_MODULE_NOT_FOUND'
  ) {
    throw error;
  }
}
const DEFAULT_CONTRACT = 'docs.contract.json';
const MARKDOWN = MarkdownIt
  ? new MarkdownIt({ html: true, linkify: false })
  : null;
const EXTERNAL_SCHEME = /^[a-z][a-z0-9+.-]*:/i;
const SAFE_EXAMPLE_COMMANDS = new Set([
  JSON.stringify(['./shifu', 'self-version']),
  JSON.stringify(['./shifu', '--version']),
]);

/** @typedef {{code: string, file: string, line: number, message: string}} Finding */
/** @typedef {{href: string, line: number}} Link */
/** @typedef {{id: string, line: number, source: string}} ExecutableExample */
/** @typedef {{rel: string, text: string, anchors: Set<string>, links: Link[], examples: ExecutableExample[]}} Document */
/**
 * @typedef {{
 *   schemaVersion: number,
 *   requiredFiles?: string[],
 *   requiredPointers?: {from: string, to: string}[],
 *   hierarchy?: {root: string, entryFiles: string[], canonicalDirectories: string[], forbiddenMarkdownRoots?: string[]},
 *   publication?: {roots: string[], include: string[], implicitCollections?: {index: string, patterns: string[]}[], allowedOrphans?: string[]},
 *   executableExamples?: {id: string, file: string, command: string[], stdoutPattern?: string, timeoutMs?: number}[]
 * }} DocsContract
 */

/** @param {string} value */
function posix(value) {
  return value.split(path.sep).join('/');
}

/** @param {string} value */
function decode(value) {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

/** @param {import('markdown-it/lib/token.mjs').default[]} children */
function headingText(children = []) {
  return children
    .filter((token) =>
      ['text', 'code_inline', 'emoji', 'image'].includes(token.type),
    )
    .map((token) => token.content)
    .join('');
}

/** @param {string} text @param {number} index */
function lineAt(text, index) {
  return text.slice(0, index).split(/\r?\n/).length;
}

/** @param {string} root */
export function markdownFiles(root = ROOT) {
  const result = spawnSync(
    'git',
    [
      'ls-files',
      '-z',
      '--cached',
      '--others',
      '--exclude-standard',
      '--',
      '*.md',
      '*.markdown',
    ],
    { cwd: root, encoding: 'utf8' },
  );
  if (result.status !== 0) {
    throw new Error(`git ls-files failed: ${(result.stderr || '').trim()}`);
  }
  return result.stdout
    .split('\0')
    .filter(Boolean)
    .filter((rel) => !rel.startsWith('framework/core/.deps/'))
    .filter((rel) => !rel.split('/').includes('node_modules'))
    .filter((rel) => fs.existsSync(path.join(root, rel)))
    .sort();
}

/** @param {string} rel @param {string} text */
export function parseDocument(rel, text) {
  const anchors = new Set();
  const links = [];
  const examples = [];
  const slugger = new GithubSlugger();

  if (MARKDOWN) {
    const tokens = MARKDOWN.parse(text, {});
    for (let index = 0; index < tokens.length; index += 1) {
      const token = tokens[index];
      if (token.type === 'heading_open') {
        const inline = tokens[index + 1];
        anchors.add(slugger.slug(headingText(inline?.children || [])));
      }
      if (token.type === 'fence') {
        const match = /(?:^|\s)docs-exec=([a-z0-9][a-z0-9-]*)\b/.exec(
          token.info,
        );
        if (match)
          examples.push({
            id: match[1],
            line: (token.map?.[0] ?? 0) + 1,
            source: token.content.trim(),
          });
      }
      if (token.type !== 'inline') continue;
      const line = (token.map?.[0] ?? 0) + 1;
      for (const child of token.children || []) {
        if (child.type === 'link_open') {
          const href = child.attrGet('href');
          if (href) links.push({ href, line });
        } else if (child.type === 'image') {
          const href = child.attrGet('src');
          if (href) links.push({ href, line });
        }
      }
    }
  } else {
    const parsed = parseReadonlyMarkdown(text);
    for (const heading of parsed.headings) anchors.add(slugger.slug(heading));
    links.push(...parsed.links);
    examples.push(...parsed.examples);
  }

  const anchorPattern =
    /<(?:a|span)\b[^>]*(?:id|name)\s*=\s*["']([^"']+)["'][^>]*>/gi;
  for (const match of text.matchAll(anchorPattern))
    anchors.add(decode(match[1]));

  const htmlLinkPattern =
    /<(?:a|img)\b[^>]*(?:href|src)\s*=\s*["']([^"']+)["'][^>]*>/gi;
  for (const match of text.matchAll(htmlLinkPattern)) {
    links.push({ href: match[1], line: lineAt(text, match.index || 0) });
  }

  return { rel, text, anchors, links, examples };
}

/** @param {string} root @param {string} contractPath */
export function readContract(root = ROOT, contractPath = DEFAULT_CONTRACT) {
  const contract = JSON.parse(
    fs.readFileSync(path.join(root, contractPath), 'utf8'),
  );
  if (contract.schemaVersion !== 2) {
    throw new Error(
      `${contractPath}: unsupported schemaVersion ${String(contract.schemaVersion)}`,
    );
  }
  return /** @type {DocsContract} */ (contract);
}

/** @param {string} root @param {string} sourceRel @param {string} href */
function resolveLocal(root, sourceRel, href) {
  const trimmed = href.trim().replace(/^<|>$/g, '');
  if (!trimmed || trimmed.startsWith('//') || EXTERNAL_SCHEME.test(trimmed)) {
    return null;
  }
  const hashAt = trimmed.indexOf('#');
  const withoutFragment = hashAt >= 0 ? trimmed.slice(0, hashAt) : trimmed;
  const fragment = hashAt >= 0 ? decode(trimmed.slice(hashAt + 1)) : '';
  const queryAt = withoutFragment.indexOf('?');
  const pathname = decode(
    queryAt >= 0 ? withoutFragment.slice(0, queryAt) : withoutFragment,
  );
  const target = pathname
    ? path.resolve(
        pathname.startsWith('/')
          ? root
          : path.dirname(path.join(root, sourceRel)),
        pathname.startsWith('/') ? `.${pathname}` : pathname,
      )
    : path.join(root, sourceRel);
  return { target, fragment };
}

/** @param {string} root @param {string} absolute */
function relativeInside(root, absolute) {
  const rel = path.relative(root, absolute);
  if (rel === '..' || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) {
    return null;
  }
  return posix(rel);
}

/** @param {string} root @param {string} absolute */
function hasExactCase(root, absolute) {
  const rel = relativeInside(root, absolute);
  if (rel === null) return false;
  let current = root;
  for (const segment of rel.split('/').filter(Boolean)) {
    if (!fs.readdirSync(current).includes(segment)) return false;
    current = path.join(current, segment);
  }
  return true;
}

/**
 * @param {{root?: string, files?: string[], contract?: DocsContract, vocabularyRegistry?: object | false, metadataContract?: object | false}} options
 * @returns {Finding[]}
 */
export function checkDocs(options = {}) {
  const root = path.resolve(options.root || ROOT);
  const files = options.files || markdownFiles(root);
  const contract = options.contract || readContract(root);
  /** @type {Map<string, Document>} */
  const documents = new Map();
  /** @type {Finding[]} */
  const findings =
    options.vocabularyRegistry === false
      ? []
      : validateVocabularyContract({
          root,
          registry: /** @type {any} */ (options.vocabularyRegistry),
        });

  if (options.metadataContract !== false) {
    findings.push(
      ...validateDocumentMetadata({
        root,
        files,
        contract: /** @type {any} */ (options.metadataContract),
      }),
    );
  }

  for (const rel of files) {
    const text = fs.readFileSync(path.join(root, rel), 'utf8');
    documents.set(rel, parseDocument(rel, text));
  }

  const hierarchy = contract.hierarchy;
  if (hierarchy) {
    const hierarchyRoot = hierarchy.root.replace(/\/$/, '');
    const entries = new Set(hierarchy.entryFiles || []);
    const canonicalDirectories = hierarchy.canonicalDirectories || [];
    const forbiddenMarkdownRoots = (hierarchy.forbiddenMarkdownRoots || []).map(
      (directory) => directory.replace(/\/$/, ''),
    );
    for (const rel of files) {
      const retiredRoot = forbiddenMarkdownRoots.find(
        (directory) => rel === directory || rel.startsWith(`${directory}/`),
      );
      if (retiredRoot) {
        findings.push({
          code: 'documentation-retired-root',
          file: rel,
          line: 1,
          message: `Markdown is forbidden under retired documentation root: ${retiredRoot}`,
        });
      }
    }
    for (const rel of files.filter(
      (file) => file.startsWith(`${hierarchyRoot}/`) || file === hierarchyRoot,
    )) {
      if (path.posix.dirname(rel) === hierarchyRoot) {
        if (!entries.has(rel)) {
          findings.push({
            code: 'documentation-hierarchy-root',
            file: rel,
            line: 1,
            message: 'root Markdown must be a declared entry file',
          });
        }
        continue;
      }
      if (
        !canonicalDirectories.some(
          (directory) => rel === directory || rel.startsWith(`${directory}/`),
        )
      ) {
        findings.push({
          code: 'documentation-hierarchy-directory',
          file: rel,
          line: 1,
          message:
            'canonical documentation is outside the declared directory taxonomy',
        });
      }
    }
  }

  for (const rel of contract.requiredFiles || []) {
    if (!fs.existsSync(path.join(root, rel))) {
      findings.push({
        code: 'required-file',
        file: rel,
        line: 1,
        message: 'required documentation surface is missing',
      });
    }
  }

  for (const document of documents.values()) {
    for (const link of document.links) {
      const local = resolveLocal(root, document.rel, link.href);
      if (!local) continue;
      const targetRel = relativeInside(root, local.target);
      if (!targetRel) {
        findings.push({
          code: 'outside-root',
          file: document.rel,
          line: link.line,
          message: `local link escapes the repository: ${link.href}`,
        });
        continue;
      }
      if (!fs.existsSync(local.target)) {
        findings.push({
          code: 'missing-target',
          file: document.rel,
          line: link.line,
          message: `local link target does not exist: ${link.href}`,
        });
        continue;
      }
      if (!hasExactCase(root, local.target)) {
        findings.push({
          code: 'case-mismatch',
          file: document.rel,
          line: link.line,
          message: `local link path casing does not match the repository: ${link.href}`,
        });
        continue;
      }
      if (!local.fragment || !/\.(?:md|markdown)$/i.test(targetRel)) continue;
      let target = documents.get(targetRel);
      if (!target) {
        target = parseDocument(
          targetRel,
          fs.readFileSync(local.target, 'utf8'),
        );
        documents.set(targetRel, target);
      }
      if (!target.anchors.has(local.fragment)) {
        findings.push({
          code: 'missing-anchor',
          file: document.rel,
          line: link.line,
          message: `Markdown anchor does not exist: ${link.href}`,
        });
      }
    }
  }

  for (const pointer of contract.requiredPointers || []) {
    const source = documents.get(pointer.from);
    if (!source) continue;
    const found = source.links.some((link) => {
      const local = resolveLocal(root, pointer.from, link.href);
      return local && relativeInside(root, local.target) === pointer.to;
    });
    if (!found) {
      findings.push({
        code: 'required-pointer',
        file: pointer.from,
        line: 1,
        message: `required documentation pointer is missing: ${pointer.to}`,
      });
    }
  }

  const declaredExamples = new Map(
    (contract.executableExamples || []).map((example) => [example.id, example]),
  );
  const observedExamples = new Map();
  for (const document of documents.values()) {
    for (const example of document.examples) {
      if (observedExamples.has(example.id)) {
        findings.push({
          code: 'executable-example-duplicate',
          file: document.rel,
          line: example.line,
          message: `duplicate executable example id: ${example.id}`,
        });
        continue;
      }
      observedExamples.set(example.id, { ...example, file: document.rel });
      const declaration = declaredExamples.get(example.id);
      if (!declaration) {
        findings.push({
          code: 'executable-example-undeclared',
          file: document.rel,
          line: example.line,
          message: `executable example is not declared in ${DEFAULT_CONTRACT}: ${example.id}`,
        });
      } else if (
        declaration.file !== document.rel ||
        declaration.command.join(' ') !== example.source
      ) {
        findings.push({
          code: 'executable-example-drift',
          file: document.rel,
          line: example.line,
          message: `executable example differs from its safe command contract: ${example.id}`,
        });
      }
    }
  }
  for (const declaration of declaredExamples.values()) {
    if (!observedExamples.has(declaration.id))
      findings.push({
        code: 'executable-example-missing',
        file: declaration.file,
        line: 1,
        message: `declared executable example is missing: ${declaration.id}`,
      });
    if (
      !Array.isArray(declaration.command) ||
      !declaration.command.length ||
      !Number.isInteger(declaration.timeoutMs) ||
      declaration.timeoutMs < 100 ||
      declaration.timeoutMs > 30000
    )
      findings.push({
        code: 'executable-example-contract',
        file: DEFAULT_CONTRACT,
        line: 1,
        message: `invalid bounded command contract: ${declaration.id}`,
      });
    else if (!SAFE_EXAMPLE_COMMANDS.has(JSON.stringify(declaration.command)))
      findings.push({
        code: 'executable-example-unsafe',
        file: DEFAULT_CONTRACT,
        line: 1,
        message: `command is not in the side-effect-free documentation allowlist: ${declaration.id}`,
      });
    if (declaration.stdoutPattern) {
      try {
        new RegExp(declaration.stdoutPattern);
      } catch {
        findings.push({
          code: 'executable-example-contract',
          file: DEFAULT_CONTRACT,
          line: 1,
          message: `invalid stdoutPattern: ${declaration.id}`,
        });
      }
    }
  }

  const publication = contract.publication;
  if (publication) {
    const included = new Set(
      files.filter((rel) =>
        publication.include.some(
          (entry) => rel === entry || rel.startsWith(`${entry}/`),
        ),
      ),
    );
    const allowed = new Set(publication.allowedOrphans || []);
    const reachable = new Set(
      publication.roots.filter((rel) => included.has(rel)),
    );
    const queue = [...reachable];
    while (queue.length) {
      const sourceRel = queue.shift();
      const source = documents.get(sourceRel);
      for (const link of source?.links || []) {
        const local = resolveLocal(root, sourceRel, link.href);
        if (!local) continue;
        const targetRel = relativeInside(root, local.target);
        if (targetRel && included.has(targetRel) && !reachable.has(targetRel)) {
          reachable.add(targetRel);
          queue.push(targetRel);
        }
      }
      for (const collection of publication.implicitCollections || []) {
        if (collection.index !== sourceRel) continue;
        const patterns = collection.patterns.map((value) => new RegExp(value));
        for (const candidate of included) {
          if (
            !reachable.has(candidate) &&
            patterns.some((pattern) => pattern.test(candidate))
          ) {
            reachable.add(candidate);
            queue.push(candidate);
          }
        }
      }
    }
    for (const rel of included) {
      if (!reachable.has(rel) && !allowed.has(rel))
        findings.push({
          code: 'publication-orphan',
          file: rel,
          line: 1,
          message: 'public document is unreachable from every publication root',
        });
    }
    for (const rel of allowed) {
      if (!included.has(rel) || reachable.has(rel))
        findings.push({
          code: 'publication-orphan-exception',
          file: DEFAULT_CONTRACT,
          line: 1,
          message: `stale or invalid allowed orphan: ${rel}`,
        });
    }
  }

  return findings.sort(
    (left, right) =>
      left.file.localeCompare(right.file) || left.line - right.line,
  );
}

function main() {
  const files = markdownFiles(ROOT);
  const findings = checkDocs({ root: ROOT, files });
  if (!findings.length) {
    console.log(
      `[docs] checked ${files.length} Markdown files; local links, anchors, and documentation contracts passed`,
    );
    return;
  }
  console.error('[docs] documentation gate violations:');
  for (const finding of findings) {
    console.error(
      `  ${finding.file}:${finding.line} [${finding.code}] ${finding.message}`,
    );
  }
  process.exit(1);
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  main();
}

